// Classify incoming message type: location, voice, or text
const msg = $input.first().json.message || $input.first().json;
const chat_id = (msg.chat && msg.chat.id) ? msg.chat.id.toString() : '';
const first_name = (msg.from && msg.from.first_name) ? msg.from.first_name : 'Fisher';

let msg_type = 'text';
if (msg.location) {
  msg_type = 'location';
} else if (msg.voice || msg.audio) {
  msg_type = 'voice';
}

return [{
  json: {
    msg_type,
    chat_id,
    first_name,
    text: msg.text || '',
    location: msg.location || null,
    voice: msg.voice || msg.audio || null,
    message_id: msg.message_id || null,
    raw: msg
  }
}];

// Extract GPS and store location via backend
const input = $input.first().json;

if (!input.location || input.location.latitude === undefined) {
  return [{ json: { chat_id: input.chat_id || '', first_name: input.first_name || 'Fisher', lat: null, lon: null, error: 'no_location' } }];
}

const lat = input.location.latitude;
const lon = input.location.longitude;
const chat_id = input.chat_id;
const first_name = input.first_name;

return [{ json: { lat, lon, chat_id, first_name } }];

const data = $input.first().json;
const loc = $('Extract Location').first().json;

let msg = `📍 *OCEAN SENTRY — LOCATION RECEIVED*\n`;
msg += `${loc.lat.toFixed(4)}° N, ${loc.lon.toFixed(4)}° E\n\n`;

// Suitability
const suitEmoji = data.suitability === 'high' ? '🟢' : data.suitability === 'moderate' ? '🟡' : data.suitability === 'low' ? '🔴' : '⚪';
msg += `🎣 *Fishing Suitability:* ${suitEmoji} ${data.suitability.toUpperCase()}\n`;
msg += `Score: ${(data.suitability_score * 100).toFixed(0)}%\n\n`;

// Environmental data
if (data.sst && data.sst.availability === 'available') {
  msg += `🌡 *SST:* ${data.sst.value}°C\n`;
}
if (data.current_speed && data.current_speed.availability === 'available') {
  msg += `🌊 *Current:* ${data.current_speed.value} m/s\n`;
}
if (data.salinity && data.salinity.availability === 'available') {
  msg += `🧂 *Salinity:* ${data.salinity.value} PSU\n`;
}
if (data.chlorophyll && data.chlorophyll.availability === 'unavailable') {
  msg += `🟢 *Chlorophyll:* unavailable\n`;
}
if (data.wave_height && data.wave_height.availability === 'unavailable') {
  msg += `🌊 *Wave Height:* unavailable\n`;
}

msg += `\n🌊 *Sea Condition:* ${(data.sea_condition || 'unknown').toUpperCase()}\n`;

// Anomalies
if (data.anomaly_count > 0) {
  msg += `⚠️ *${data.anomaly_count} ocean anomalies* detected nearby\n`;
}

// Recommended zone
if (data.recommended_zone) {
  const rz = data.recommended_zone;
  msg += `\n📌 *Recommended Zone:*\n`;
  msg += `${rz.latitude.toFixed(2)}° N, ${rz.longitude.toFixed(2)}° E\n`;
  msg += `~${rz.distance_km.toFixed(0)} km away | ${rz.suitability.toUpperCase()}\n`;
  msg += `Reason: ${rz.reason}\n`;
}

// Factors
if (data.suitability_factors && data.suitability_factors.length > 0) {
  msg += `\n📊 *Analysis:*\n`;
  for (const f of data.suitability_factors) {
    msg += `• ${f}\n`;
  }
}

msg += `\n_${data.disclaimer || 'Environmental suitability assessment — not a fish prediction.'}_`;
if (data.data_freshness_hours) {
  msg += `\n\n🕐 Data: ${data.data_source || 'Ocean Sentry'} (${Math.round(data.data_freshness_hours)}h ago)`;
} else {
  msg += `\n\n🕐 Data: ${data.data_source || 'Ocean Sentry'}`;
}

return [{ json: { chat_id: loc.chat_id, text: msg } }];

// Voice message: download file via Telegram API and send to STT
const input = $input.first().json;
const voice = input.voice;
const chat_id = input.chat_id;
const first_name = input.first_name;

if (!voice || !voice.file_id) {
  return [{ json: { chat_id, error: true, text: '⚠️ Could not process voice message. Please try again or send text.' } }];
}

return [{ json: { chat_id, first_name, file_id: voice.file_id, duration: voice.duration || 0 } }];

const item = $input.first();

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

return {
  json: {
    ...item.json,
    base64Audio: buffer.toString('base64'),
    mimeType: item.binary?.data?.mimeType || 'audio/ogg'
  }
};

