const input = $input.first().json;

// Get original Telegram information
const telegram = $('Telegram Trigger').first().json;

// Extract transcription from Gemini
let text = '';

try {
  if (
    input.candidates &&
    input.candidates[0] &&
    input.candidates[0].content &&
    input.candidates[0].content.parts
  ) {
    text = input.candidates[0].content.parts
      .map(p => p.text || '')
      .join('')
      .trim();
  }
} catch (e) {
  text = '';
}

// Telegram chat ID
const chat_id =
  telegram.message?.chat?.id ||
  telegram.chat_id ||
  telegram.callback_query?.message?.chat?.id;

// First name
const first_name =
  telegram.message?.from?.first_name ||
  telegram.first_name ||
  'Fisher';

return [{
  json: {
    chat_id,
    first_name,
    text,
    transcription_failed: !text,
    msg_type: 'text'
  }
}];

// Deterministic intent router
const input = $input.first().json;
const text = (input.text || '').toLowerCase().trim();
const chat_id = input.chat_id;
const first_name = input.first_name || 'Fisher';

let intent = 'unknown';

// Pattern groups — order matters (most specific first)
const zonePatterns = ['where should i fish', 'best fishing', 'find fishing', 'fishing zone', 'recommend', 'zone', 'best spot', 'good area'];
const fishingPatterns = ['fish', 'suitable', 'suitability', 'good to fish', 'can i fish', 'fishing here', 'machhli', 'meen', 'matsya'];
const seaPatterns = [
  // English
  'sea',
  'ocean',
  'conditions',
  'sea conditions',
  'sea condition',
  'sea state',
  'ocean conditions',
  'how is the sea',
  'weather',
  'waves',
  'current',

  // Tamil
  'கடல்',
  'கடலின்',
  'கடலின் நிலைமை',
  'கடல் நிலைமை',
  'கடல் நிலவரம்',
  'கடல் நிலை எப்படி',
  'கடலின் நிலைமை எப்படி',
  'கடலின் நிலைமை எப்படி இருக்கிறது',
  'கடல் எப்படி இருக்கிறது',
  'அலை',
  'அலைகள்',
  'கடல் அலை',
  'நீரோட்டம்',

  // Tamil transliteration
  'kadal',
  'kadalin',
  'kadal nilamai',
  'kadalin nilamai',
  'kadal eppadi irukku',
  'kadal eppadi irukku',
  'alai',
  'alaigal',
  'neerottam',
  'samudra'
];
const alertPatterns = ['alert', 'warning', 'safe', 'danger', 'is it safe', 'khabar', 'risk'];
const subscribePatterns = ['subscribe', 'notify me', 'alerts on', 'alert me', 'send alert', 'watch'];
const unsubscribePatterns = ['unsubscribe', 'stop alert', 'alerts off', 'no more', 'cancel alert'];
const helpPatterns = ['/start', '/help', 'help', 'menu', 'start', 'hi', 'hello', 'hey'];

if (text === '/start' || text === '/help' || helpPatterns.some(p => text === p || text.startsWith(p + ' '))) {
  intent = 'help';
} else if (text === '/unsubscribe' || unsubscribePatterns.some(p => text.includes(p))) {
  intent = 'unsubscribe';
} else if (text === '/subscribe' || subscribePatterns.some(p => text.includes(p))) {
  intent = 'subscribe';
} else if (text === '/zone' || zonePatterns.some(p => text.includes(p))) {
  intent = 'zone_recommendation';
} else if (text === '/fish' || fishingPatterns.some(p => text.includes(p))) {
  intent = 'fishing_intelligence';
} else if (text === '/sea' || seaPatterns.some(p => text.includes(p))) {
  intent = 'sea_conditions';
} else if (text === '/alerts' || alertPatterns.some(p => text.includes(p))) {
  intent = 'coastal_alerts';
}

return [{ json: { intent, chat_id, first_name, text: input.text } }];

const input = $input.first().json;
const intentData = $('Parse Intent').first().json;
const chat_id = intentData.chat_id;

// Check if we got a location or an error
if (input.latitude && input.longitude) {
  return [{ json: { chat_id, lat: input.latitude, lon: input.longitude, has_location: true, intent: intentData.intent } }];
}

// No stored location
return [{ json: { chat_id, has_location: false, intent: intentData.intent } }];

const data = $input.first().json;
const loc = $('Check Has Location').first().json;
const route = $('Route API Call').first().json;

let msg = `🎣 *OCEAN SENTRY — FISHING INTELLIGENCE*\n\n`;

msg += `📍 *Your Location:* ${loc.lat.toFixed(4)}°N, ${loc.lon.toFixed(4)}°E\n\n`;

const suitEmoji =
  data.suitability === 'high' ? '🟢' :
  data.suitability === 'moderate' ? '🟡' :
  data.suitability === 'low' ? '🔴' : '⚪';

msg += `🎣 *Fishing Suitability:* ${data.suitability.toUpperCase()} — ${(data.suitability_score * 100).toFixed(0)}%\n\n`;

if (data.sst?.availability === 'available') {
  msg += `🌡️ *SST:* ${data.sst.value}°C\n`;
}

if (data.salinity?.availability === 'available') {
  msg += `🧂 *Salinity:* ${data.salinity.value} PSU\n`;
}

if (data.current_speed?.availability === 'available') {
  msg += `🌊 *Current:* ${data.current_speed.value} m/s\n`;
}

msg += `🌊 *Sea Condition:* ${(data.sea_condition || 'unknown').toUpperCase()}\n\n`;

if (data.anomaly_count > 0) {
  msg += `⚠️ *Ocean Anomalies:* ${data.anomaly_count} anomaly observations detected.\n\n`;
}

if (data.recommended_zone) {
  const z = data.recommended_zone;

  msg += `📌 *Recommended Fishing Zone*\n`;
  msg += `📍 ${z.latitude.toFixed(4)}°N, ${z.longitude.toFixed(4)}°E\n`;
  msg += `🎣 Suitability: *${z.suitability.toUpperCase()}* — ${(z.suitability_score * 100).toFixed(1)}%\n`;
  msg += `📏 Distance: ${z.distance_km.toFixed(1)} km\n`;
  msg += `💡 ${z.reason}\n\n`;
}

if (data.data_freshness_hours != null) {
  const hours = Number(data.data_freshness_hours);
  const days = (hours / 24).toFixed(1);

  msg += `🕐 *Data Freshness*\n`;
  msg += `${hours.toFixed(0)} hours (~${days} days old)\n\n`;
}

msg += `🛰️ *Data Source*\n`;
msg += `${data.data_source ?? 'Ocean data'}\n\n`;

msg += `⚠️ _Environmental suitability assessment only._\n`;
msg += `_Not a guaranteed fish-location prediction._`;

return [
  {
    json: {
      chat_id: route.chat_id,
      text: msg,
      intelligence: data
    }
  }
];

const data = $input.first().json;
const loc = $('Check Has Location').first().json;

let msg = `🌊 *OCEAN SENTRY — SEA CONDITIONS*\n\n`;
msg += `📍 ${loc.lat.toFixed(4)}° N, ${loc.lon.toFixed(4)}° E\n\n`;

if (data.sst && data.sst.availability === 'available') msg += `🌡 *SST:* ${data.sst.value}°C\n`;
else msg += `🌡 *SST:* unavailable\n`;

if (data.salinity && data.salinity.availability === 'available') msg += `🧂 *Salinity:* ${data.salinity.value} PSU\n`;
if (data.current_speed && data.current_speed.availability === 'available') msg += `💨 *Current Speed:* ${data.current_speed.value} m/s\n`;
if (data.current_direction && data.current_direction.availability === 'available') msg += `🧭 *Direction:* ${data.current_direction.value}°\n`;
if (data.wave_height && data.wave_height.availability === 'unavailable') msg += `🌊 *Wave Height:* unavailable\n`;

msg += `\n🌊 *Overall:* ${(data.overall_condition || 'unknown').toUpperCase()}\n`;
if (data.anomaly_count > 0) msg += `⚠️ *Anomalies:* ${data.anomaly_count} detected\n`;
if (data.warnings && data.warnings.length > 0) {
  msg += `\n*Warnings:*\n`;
  for (const w of data.warnings.slice(0, 3)) msg += `• ${w}\n`;
}

msg += `\n📡 ${data.data_source || 'Ocean Sentry'}`;
if (data.data_freshness_hours) msg += ` (${Math.round(data.data_freshness_hours)}h ago)`;

return [{ json: { chat_id: loc.chat_id, text: msg } }];

const data = $input.first().json;
const loc = $('Check Has Location').first().json;

let msg = '';
if (data.found) {
  const rz = data.recommendation;
  const suitEmoji = rz.suitability === 'high' ? '🟢' : rz.suitability === 'moderate' ? '🟡' : '🔴';
  msg = `📌 *OCEAN SENTRY — RECOMMENDED ZONE*\n\n`;
  msg += `📍 *Recommended:* ${rz.latitude.toFixed(4)}° N, ${rz.longitude.toFixed(4)}° E\n`;
  msg += `📏 *Distance:* ~${rz.distance_km.toFixed(0)} km from your location\n`;
  msg += `🎯 *Suitability:* ${suitEmoji} ${rz.suitability.toUpperCase()} (${(rz.suitability_score * 100).toFixed(0)}%)\n`;
  msg += `💡 *Reason:* ${rz.reason}\n`;
  msg += `\n📍 *Your location:* ${data.current_location_suitability.toUpperCase()}\n`;
  msg += `\n📡 ${data.data_source || 'Ocean Sentry'}`;
  msg += `\n\n_${data.disclaimer || 'Environmental suitability assessment only.'}_`;
} else {
  msg = `📌 *OCEAN SENTRY — ZONE RECOMMENDATION*\n\n`;
  msg += `❌ No suitable fishing zone found within the search radius.\n\n`;
  msg += `This may be due to insufficient ocean data coverage in this area.\n`;
  msg += `Try again with a larger search area or at a different location.`;
}

return [{ json: { chat_id: loc.chat_id, text: msg } }];

const data = $input.first().json;
const loc = $('Check Has Location').first().json;

let msg = `🚨 *OCEAN SENTRY — COASTAL ALERTS*\n\n`;
msg += `📍 ${loc.lat.toFixed(4)}° N, ${loc.lon.toFixed(4)}° E\n\n`;

if (data.alerts && data.alerts.length > 0) {
  for (const a of data.alerts) {
    msg += `⚠️ *${a.alert_type.toUpperCase()}* (${a.severity})\n`;
    msg += `${a.message}\n`;
    msg += `Source: ${a.source} | Verified: ${a.verified ? 'Yes' : 'No'}\n\n`;
  }
}

msg += `ℹ️ ${data.message}\n`;
msg += `\n📡 ${data.data_source || 'Ocean Sentry'}`;

return [{ json: { chat_id: loc.chat_id, text: msg } }];

// Subscribe: need location first
const input = $input.first().json;
const chat_id = input.chat_id;

return [{ json: { chat_id } }];

const input = $input.first().json;
const chat_id = $('Handle Subscribe').first().json.chat_id;

if (input.latitude && input.longitude) {
  return [{ json: { chat_id, lat: input.latitude, lon: input.longitude, has_location: true } }];
}
return [{ json: { chat_id, has_location: false } }];

const input = $input.first().json;
const chat_id = input.chat_id;

return [{ json: { chat_id } }];

const input = $input.first().json;
const intentData = $('Parse Intent').first().json;
const chat_id = intentData.chat_id;

// Check if we got a location or an error
if (input.latitude && input.longitude) {
  return [{ json: { chat_id, lat: input.latitude, lon: input.longitude, has_location: true, intent: intentData.intent } }];
}

// No stored location
return [{ json: { chat_id, has_location: false, intent: intentData.intent } }];

const data = $input.first().json;

const loc = $('Has Location?sea').first().json;

let msg = `🌊 *OCEAN SENTRY — SEA CONDITIONS*\n\n`;

msg += `📍 *Location:* ${Number(data.latitude).toFixed(4)}°N, ${Number(data.longitude).toFixed(4)}°E\n\n`;

if (data.sst?.availability === 'available') {
  msg += `🌡️ *Sea Surface Temperature:* ${data.sst.value}°C\n`;
}

if (data.salinity?.availability === 'available') {
  msg += `🧂 *Salinity:* ${data.salinity.value} PSU\n`;
}

if (data.current_speed?.availability === 'available') {
  msg += `🌊 *Current Speed:* ${data.current_speed.value} m/s\n`;
}

if (data.current_direction?.availability === 'available') {
  msg += `🧭 *Current Direction:* ${data.current_direction.value}°\n`;
}

if (data.sea_condition) {
  msg += `🌤️ *Sea Condition:* ${String(data.sea_condition).toUpperCase()}\n`;
}

if (data.wave_height?.availability === 'available') {
  msg += `〰️ *Wave Height:* ${data.wave_height.value} m\n`;
}

if (data.sea_level?.availability === 'available') {
  msg += `📏 *Sea Level:* ${data.sea_level.value} m\n`;
}

msg += `\n`;

if (data.anomaly_count !== undefined) {
  if (data.anomaly_count > 0) {
    msg += `⚠️ *Ocean Anomalies:* ${data.anomaly_count} observations detected.\n`;
  } else {
    msg += `✅ *Ocean Anomalies:* None detected.\n`;
  }
}

if (data.data_freshness_hours != null) {
  const hours = Number(data.data_freshness_hours);
  const days = (hours / 24).toFixed(1);

  msg += `\n🕐 *Data Freshness:* ${hours.toFixed(0)} hours (~${days} days old)\n`;
}

msg += `\n🛰️ *Data Source:* ${data.data_source ?? 'Ocean data'}\n`;

msg += `\n⚠️ _These are environmental sea conditions based on available ocean data._`;

return [
  {
    json: {
      chat_id: loc.chat_id,
      text: msg,
      sea_conditions: data
    }
  }
];
